from pathlib import Path

root = Path('.')
editor_path = root / 'triaz_groove_builder' / 'editor.py'
s = editor_path.read_text(encoding='utf-8')
start = s.index('        # Waveform.\n', s.index('    def redraw(self):'))
end = s.index('        # Draw actual playback occurrences.', start)
replacement = '''        # Classify source transients once. Classification is used to colour the\n        # waveform itself; source evidence is not painted as guide lines through\n        # the sequencer grid.\n        if self.index not in self.transient_cache:\n            self.transient_cache[self.index] = source_transient_families(y, sr)\n        trans_t, trans_s, trans_family = self.transient_cache[self.index]\n\n        # Filled source waveform, colour-coded by detected drum family. The\n        # colours deliberately match the editor lanes: kick red, snare/clap\n        # amber, hats cyan, other percussion blue. Unclassified gaps stay grey.\n        if y.size:\n            bins = max(260, int(x1 - x0))\n            edges = np.linspace(0, len(y), bins + 1, dtype=int)\n            peak = max(float(np.max(np.abs(y))), 1e-9)\n            mid = self.wave_top + self.wave_h / 2.0\n            xs = np.empty(bins, dtype=float)\n            amps = np.empty(bins, dtype=float)\n            for i in range(bins):\n                seg = y[edges[i]:edges[i + 1]]\n                amps[i] = float(np.max(np.abs(seg))) / peak if len(seg) else 0.0\n                xs[i] = x0 + (x1 - x0) * (i / max(1, bins - 1))\n\n            fam_for_bin = np.full(bins, -1, dtype=int)\n            if len(trans_t):\n                bin_times = ((edges[:-1] + edges[1:]) * 0.5) / float(sr)\n                pos = np.searchsorted(trans_t, bin_times)\n                prev_idx = np.clip(pos - 1, 0, len(trans_t) - 1)\n                next_idx = np.clip(pos, 0, len(trans_t) - 1)\n                prev_d = np.abs(bin_times - trans_t[prev_idx])\n                next_d = np.abs(bin_times - trans_t[next_idx])\n                nearest = np.where(next_d < prev_d, next_idx, prev_idx)\n                nearest_d = np.minimum(prev_d, next_d)\n                nearest_fam = np.asarray(trans_family, dtype=int)[nearest]\n                windows = np.where(\n                    nearest_fam == 0, 0.20,\n                    np.where(nearest_fam == 2, 0.14,\n                             np.where(nearest_fam == 6, 0.075, 0.11)),\n                )\n                active = nearest_d <= windows\n                fam_for_bin[active] = nearest_fam[active]\n\n            run_start = 0\n            while run_start < bins:\n                fam = int(fam_for_bin[run_start])\n                run_end = run_start + 1\n                while run_end < bins and int(fam_for_bin[run_end]) == fam:\n                    run_end += 1\n                color = SOURCE_FAMILY_COLORS.get(fam, '#7c858d') if fam >= 0 else '#7c858d'\n                upper, lower = [], []\n                for i in range(run_start, run_end):\n                    amp = amps[i]\n                    upper.extend((xs[i], mid - amp * (self.wave_h * 0.42)))\n                    lower.extend((xs[i], mid + amp * (self.wave_h * 0.42)))\n                if len(upper) >= 4:\n                    c.create_polygon(*(upper + list(reversed(lower))), fill=color, outline='')\n                run_start = run_end\n\n        # Clean TRIAZ-style grid. A 1/32-note grid across four bars would mean\n        # 128 columns and would be denser than TRIAZ. Keep 1/16 cells: very faint\n        # step lines, clearer quarter notes, strongest bar lines. Only bars extend\n        # through the waveform so the waveform remains visually clean.\n        base_step = self._base_step()\n        ngrid = max(1, int(math.floor(duration / base_step + 1e-6)))\n        for i in range(ngrid + 1):\n            t = i * base_step\n            if t > duration + 1e-6:\n                break\n            x = self._time_to_x(t, duration)\n            if i % 16 == 0:\n                fill, width_px = '#5d6267', 2\n            elif i % 4 == 0:\n                fill, width_px = '#42464a', 1\n            else:\n                fill, width_px = '#303336', 1\n            c.create_line(x, self.lane_top, x, bottom, fill=fill, width=width_px)\n            if i % 16 == 0:\n                c.create_line(x, self.ruler_top, x, self.wave_top + self.wave_h, fill='#3f4347', width=1)\n                if i < ngrid:\n                    c.create_text(x + 4, self.ruler_top + 8, anchor='nw', fill='#a8adb2',\n                                  text=f'BAR {(i // 16) + 1}', font=('Segoe UI', 7))\n\n'''
editor_path.write_text(s[:start] + replacement + s[end:], encoding='utf-8')

for rel in ['app.py', 'launcher.py', 'installer/triaz_groove_builder.iss', 'VERSION', 'README.md']:
    p = root / rel
    text = p.read_text(encoding='utf-8').replace('0.1.12', '0.1.13')
    p.write_text(text, encoding='utf-8')
